  name: string;
  role: string;
}

interface BlogPost {
  date: string;
  title: string;
  author: BlogPostAuthor;
  href?: string;
}

interface BlogSectionHeader {
  badge: string;
  heading: string;
  description: string;
  ctaText: string;
  ctaHref: string;
}

