  header: BlogSectionHeader;
  posts: BlogPost[];
  className?: string;
  /** Optional render override for the CTA link */
  renderCtaLink?: (props: { href: string; children: React.ReactNode }) => React.ReactNode;
  /** Optional render override for individual card links */
